/* STREAMING_CHUNK:Defining constants and carrier lists... */
const CARRIERS = [
  'Wawanesa', 'Dominion', 'Intact', 'Aviva', 'Economical', 
  'Pembridge', 'Gore Mutual', 'SGI', 'Travelers', 'Chubb', 
  'Belairdirect', 'TD Insurance', 'RSA', 'Northbridge'
];
const CONSENT_KEYWORDS = ['personal', 'information', 'consent'];
const SUMMARY_KEYWORD  = 'summary';
const IGNORE_KEYWORDS   = ['pac', 'mac'];

const item = $input.first();
const subject = (item.json.subject || '').trim();
const subLow  = subject.toLowerCase();

/* STREAMING_CHUNK:Extracting Business Type, Client ID, and Carrier... */
const businessType = subLow.includes('remarket') ? 'REMARKET' : 'NEW BUSINESS';
const ccMatch  = subject.match(/CC:\\s([A-Z0-9]+)/i);
const clientId = ccMatch ? ccMatch[1].toUpperCase() : 'UNKNOWN';

let carrier = 'UNKNOWN';
for (const c of CARRIERS) {
  if (subLow.includes(c.toLowerCase())) {
    carrier = c.toUpperCase();
    break;
  }
}

/* STREAMING_CHUNK:Sorting binary attachments into buckets... */
const binary  = item.binary || {};
const buckets = { home: [], auto: [], lpv: [], shared: [], ignored: [] };

const isConsentForm = (n) => CONSENT_KEYWORDS.every(kw => n.includes(kw));

for (const [key, binData] of Object.entries(binary)) {
  const fname = (binData.fileName || '').toLowerCase();

  if (IGNORE_KEYWORDS.some(kw => fname.includes(kw))) { 
    buckets.ignored.push(key); 
    continue; 
  }

  if (fname.includes('lpv')) {
    buckets.lpv.push(key);
    continue;
  }

  if (isConsentForm(fname) || fname.includes(SUMMARY_KEYWORD)) {
    buckets.shared.push(key);
    continue;
  }

  const isHome = fname.includes('home');
  const isAuto = fname.includes('auto');

  if (isHome) buckets.home.push(key);
  if (isAuto) buckets.auto.push(key);

  if (!isHome && !isAuto) {
    buckets.shared.push(key);
  }
}

/* STREAMING_CHUNK:Calculating LPV specific product types... */
const lpvHasAuto   = buckets.lpv.some(k => (binary[k]?.fileName || '').toLowerCase().includes('auto'));
const lpvHasTenant = buckets.lpv.some(k => (binary[k]?.fileName || '').toLowerCase().includes('tenant'));
let lpvProductType = 'AUTO & TENANTS';
if (lpvHasAuto && !lpvHasTenant) lpvProductType = 'AUTO';
if (lpvHasTenant && !lpvHasAuto) lpvProductType = 'TENANTS';

/* STREAMING_CHUNK:Formatting HTML Signature...*/
const signatureHtml = `
<div style=\"font-family: Arial, sans-serif; font-size: 12px; color: #333;\">
  <p>Please find the attached signed documents for your review and processing.</p>
  <br>
  <div style=\"color: #1a3a6e; font-weight: bold; font-size: 15px;\">Oleh(Finn) Babinskyi, RIBO & LLQP</div>
  <div style=\"font-style: italic; color: #666;\">Customer Service Representative</div>
  <br>
  1430 Hurontario Street, Port Credit Mississauga, Ontario L5G 3H4<br>
  Buss: (905) 486 0440 | Dir: (905) 486 0437 | Fax: (905) 486 0441<br>
  Email: <a href=\"mailto:olehb@kmibrokers.com\">olehb@kmibrokers.com</a> | Website: <a href=\"https://www.kmibrokers.com\">www.kmibrokers.com</a>
  <br><br>
  <img src=\"cid:kmi_logo\" alt=\"KMI Brokers\" style=\"max-width: 200px;\">
  <br><br>
  <p style=\"font-size: 9px; color: #999; border-top: 1px solid #ddd; padding-top: 8px;\">
    <strong>DISCLAIMER:</strong> This email (including any attachments) is intended for the sole use of the intended recipient/s and may contain material that is CONFIDENTIAL AND PRIVATE COMPANY INFORMATION. Any review or reliance by others or copying or distribution or forwarding of any or all of the contents in this message is STRICTLY PROHIBITED.
  </p>
</div>`;

/* STREAMING_CHUNK:Preparing final routing flags and subjects... */
return [{
  json: {
    hasHome: subLow.includes('home') || buckets.home.length > 0,
    hasAuto: subLow.includes('auto') || buckets.auto.length > 0,
    hasLPV: buckets.lpv.length > 0,
    homeSubj: `${businessType} / CC: ${clientId} / HOME / BINDER:  / ${carrier}`,
    autoSubj: `${businessType} / CC: ${clientId} / AUTO / BINDER:  / ${carrier}`,
    lpvSubj: `LPV / CC: ${clientId} / ${lpvProductType} / POLICIES:  / ${carrier}`,
    homeFiles: [...buckets.home, ...buckets.shared].join(','),
    autoFiles: [...buckets.auto, ...buckets.shared].join(','),
    lpvFiles: buckets.lpv.join(','),
    signatureHtml
  },
  binary
}];
